"""HTTP entry point for StreamMill."""

from __future__ import annotations

import argparse
import json
import math
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote, urlsplit

from .service import (
    BackpressureNotEnabledError,
    BatchIdConflictError,
    BatchIngestNotEnabledError,
    ChangeCursorAheadError,
    ChangeCursorExpiredError,
    ChangeFeedNotEnabledError,
    DimensionVersionConflictError,
    EventIdConflictError,
    JoinNotEnabledError,
    LookupKeyNotFoundError,
    LookupVersionNotFoundError,
    RestoreConflictError,
    Service,
    SnapshotError,
    StateFileError,
    StatePersistError,
    StreamBackpressuredError,
    StreamExistsError,
    StreamNotFoundError,
    TableExistsError,
    TableNotFoundError,
    WatermarkRegressionError,
)


def env_address() -> tuple[str, int]:
    raw = os.environ.get("STREAMMILL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid STREAMMILL_ADDR: {raw!r}")
    return host, int(port)


def env_state_file() -> str | None:
    """Configured local state file path; None keeps in-memory behavior."""
    return os.environ.get("STREAMMILL_STATE_FILE")


class _RequestError(Exception):
    """Validation or domain failure mapped onto a JSON error response."""

    def __init__(self, status: int, code: str, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message


def _invalid_request(message: str) -> _RequestError:
    return _RequestError(422, "invalid_request", message)


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_finite_number(value: object) -> bool:
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


_CREATE_FIELDS = {
    "name": lambda v: isinstance(v, str) and len(v) > 0,
    "window_ms": lambda v: _is_int(v) and v > 0,
    "allowed_lateness_ms": lambda v: _is_int(v) and v >= 0,
}
_CREATE_OPTIONAL_FIELDS = {
    "dedup_retention_ms": lambda v: _is_int(v) and v > 0,
    "auto_watermark_lag_ms": lambda v: _is_int(v) and v >= 0,
    "slide_ms": lambda v: _is_int(v) and v > 0,
    "lookup_table": lambda v: isinstance(v, str) and len(v) > 0,
    "change_retention": lambda v: _is_int(v) and v > 0,
    "batch_retention": lambda v: _is_int(v) and v > 0,
    "max_open_windows": lambda v: _is_int(v) and v > 0,
}
_EVENT_FIELDS = {
    "timestamp_ms": _is_int,
    "value": _is_finite_number,
}
_EVENT_DEDUP_FIELDS = {
    "event_id": lambda v: isinstance(v, str) and len(v) > 0,
}
_EVENT_JOIN_FIELDS = {
    "lookup_key": lambda v: isinstance(v, str) and len(v) > 0,
}
_TABLE_FIELDS = {
    "name": lambda v: isinstance(v, str) and len(v) > 0,
}
_TABLE_OPTIONAL_FIELDS = {
    "event_time_versioned": lambda v: isinstance(v, bool),
}
_ROW_FIELDS = {
    "key": lambda v: isinstance(v, str) and len(v) > 0,
    "label": lambda v: isinstance(v, str) and len(v) > 0,
}
_ROW_VERSIONED_FIELDS = {
    **_ROW_FIELDS,
    "effective_from_ms": _is_int,
}
_WATERMARK_FIELDS = {
    "watermark_ms": _is_int,
}
_BATCH_FIELDS = {
    "batch_id": lambda v: isinstance(v, str) and len(v) > 0,
    "events": lambda v: isinstance(v, list) and 1 <= len(v) <= 1000,
}


def _validate(body: object, fields: dict, optional: dict | None = None) -> dict:
    """Check required fields, types and reject undeclared fields."""
    if not isinstance(body, dict):
        raise _invalid_request("request body must be a JSON object")
    declared = set(fields) | set(optional or ())
    extra = sorted(set(body) - declared)
    if extra:
        raise _invalid_request(f"unexpected fields: {', '.join(extra)}")
    values = {}
    for field, check in fields.items():
        if field not in body:
            raise _invalid_request(f"missing required field: {field}")
        value = body[field]
        if not check(value):
            raise _invalid_request(f"invalid value for field: {field}")
        values[field] = value
    for field, check in (optional or {}).items():
        if field in body:
            value = body[field]
            if not check(value):
                raise _invalid_request(f"invalid value for field: {field}")
            values[field] = value
    return values


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, status: int, code: str, message: str) -> None:
        self.send_json(status, {"error": {"code": code, "message": message}})

    def _segments(self) -> list[str]:
        path = urlsplit(self.path).path
        return [unquote(part) for part in path.split("/") if part]

    def _read_json(self) -> object:
        try:
            length = int(self.headers.get("Content-Length") or "0")
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            return json.loads(raw)
        except ValueError:
            raise _RequestError(400, "invalid_json", "request body is not valid JSON") from None

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        segments = self._segments()
        if segments == ["snapshot"]:
            self.send_json(200, self.service.snapshot())
            return
        if len(segments) == 3 and segments[0] == "streams" and segments[2] == "results":
            try:
                self.send_json(200, self.service.results(segments[1]))
            except StreamNotFoundError:
                self.send_error_json(404, "stream_not_found", f"unknown stream: {segments[1]}")
            return
        if len(segments) == 3 and segments[0] == "streams" and segments[2] == "joined-results":
            try:
                self.send_json(200, self.service.joined_results(segments[1]))
            except StreamNotFoundError:
                self.send_error_json(404, "stream_not_found", f"unknown stream: {segments[1]}")
            except JoinNotEnabledError:
                self.send_error_json(409, "join_not_enabled", f"stream has no lookup_table: {segments[1]}")
            return
        if len(segments) == 3 and segments[0] == "streams" and segments[2] == "changes":
            try:
                self._get_changes(segments[1])
            except _RequestError as exc:
                self.send_error_json(exc.status, exc.code, exc.message)
            return
        if len(segments) == 3 and segments[0] == "streams" and segments[2] == "pressure":
            try:
                self.send_json(200, self.service.pressure(segments[1]))
            except StreamNotFoundError:
                self.send_error_json(404, "stream_not_found", f"unknown stream: {segments[1]}")
            except BackpressureNotEnabledError:
                self.send_error_json(
                    409, "backpressure_not_enabled",
                    f"stream has no max_open_windows: {segments[1]}",
                )
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        segments = self._segments()
        try:
            if segments == ["streams"]:
                self._create_stream()
                return
            if segments == ["tables"]:
                self._create_table()
                return
            if len(segments) == 3 and segments[0] == "tables" and segments[2] == "rows":
                self._put_row(segments[1])
                return
            if len(segments) == 3 and segments[0] == "streams" and segments[2] == "events":
                self._add_event(segments[1])
                return
            if len(segments) == 3 and segments[0] == "streams" and segments[2] == "batches":
                self._add_batch(segments[1])
                return
            if len(segments) == 3 and segments[0] == "streams" and segments[2] == "watermark":
                self._advance_watermark(segments[1])
                return
            if segments == ["snapshot", "restore"]:
                self._restore_snapshot()
                return
        except _RequestError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        except StatePersistError as exc:
            self.send_error_json(503, "state_persist_failed", str(exc))
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def _create_stream(self) -> None:
        values = _validate(self._read_json(), _CREATE_FIELDS, _CREATE_OPTIONAL_FIELDS)
        retention = values.get("dedup_retention_ms")
        if retention is not None and retention < values["allowed_lateness_ms"]:
            raise _invalid_request(
                "dedup_retention_ms must be at least allowed_lateness_ms"
            )
        slide = values.get("slide_ms")
        if slide is not None and (
            slide > values["window_ms"] or values["window_ms"] % slide != 0
        ):
            raise _invalid_request(
                "slide_ms must be no larger than window_ms and evenly divide it"
            )
        try:
            payload = self.service.create_stream(
                values["name"],
                values["window_ms"],
                values["allowed_lateness_ms"],
                retention,
                values.get("auto_watermark_lag_ms"),
                slide,
                values.get("lookup_table"),
                values.get("change_retention"),
                values.get("batch_retention"),
                values.get("max_open_windows"),
            )
        except StreamExistsError:
            raise _RequestError(409, "stream_exists", f"stream already exists: {values['name']}") from None
        except TableNotFoundError:
            raise _invalid_request(
                f"unknown lookup_table: {values['lookup_table']}"
            ) from None
        self.send_json(201, payload)

    def _create_table(self) -> None:
        values = _validate(self._read_json(), _TABLE_FIELDS, _TABLE_OPTIONAL_FIELDS)
        try:
            payload = self.service.create_table(
                values["name"], values.get("event_time_versioned", False)
            )
        except TableExistsError:
            raise _RequestError(409, "table_exists", f"table already exists: {values['name']}") from None
        self.send_json(201, payload)

    def _put_row(self, table: str) -> None:
        body = self._read_json()
        features = self.service.table_features(table)
        versioned = features is not None and features["event_time_versioned"]
        # Unknown tables validate against the base shape, matching the
        # event route's 422-before-404 ordering; effective_from_ms stays
        # undeclared there and on current-value tables.
        values = _validate(body, _ROW_VERSIONED_FIELDS if versioned else _ROW_FIELDS)
        try:
            if versioned:
                payload = self.service.put_version_row(
                    table, values["key"], values["label"], values["effective_from_ms"]
                )
            else:
                payload = self.service.put_row(table, values["key"], values["label"])
        except TableNotFoundError:
            raise _RequestError(404, "table_not_found", f"unknown table: {table}") from None
        except DimensionVersionConflictError as exc:
            raise _RequestError(409, "dimension_version_conflict", str(exc)) from None
        self.send_json(200, payload)

    def _add_event(self, name: str) -> None:
        body = self._read_json()
        features = self.service.stream_features(name)
        fields = dict(_EVENT_FIELDS)
        if features is not None:
            if features["dedup"]:
                fields.update(_EVENT_DEDUP_FIELDS)
            if features["join"]:
                fields.update(_EVENT_JOIN_FIELDS)
        # Unknown streams validate against the base shape, matching the
        # historical 422-before-404 ordering; event_id and lookup_key stay
        # undeclared there.
        values = _validate(body, fields)
        try:
            payload = self.service.add_event(
                name,
                values["timestamp_ms"],
                values["value"],
                values.get("event_id"),
                values.get("lookup_key"),
            )
        except StreamNotFoundError:
            raise _RequestError(404, "stream_not_found", f"unknown stream: {name}") from None
        except EventIdConflictError:
            raise _RequestError(
                409, "event_id_conflict", f"conflicting event_id: {values['event_id']}"
            ) from None
        except LookupKeyNotFoundError:
            raise _RequestError(
                409, "lookup_key_not_found", f"unknown lookup_key: {values['lookup_key']}"
            ) from None
        except LookupVersionNotFoundError:
            raise _RequestError(
                409, "lookup_version_not_found",
                f"no dimension version for lookup_key: {values['lookup_key']}",
            ) from None
        except StreamBackpressuredError:
            raise _RequestError(
                429, "stream_backpressured", f"stream has no open window slots: {name}"
            ) from None
        self.send_json(200, payload)

    def _add_batch(self, name: str) -> None:
        values = _validate(self._read_json(), _BATCH_FIELDS)
        features = self.service.stream_features(name)
        fields = dict(_EVENT_FIELDS)
        if features is not None:
            if features["dedup"]:
                fields.update(_EVENT_DEDUP_FIELDS)
            if features["join"]:
                fields.update(_EVENT_JOIN_FIELDS)
        # Every element is validated before anything is applied, so a
        # structural failure anywhere rejects the whole batch. Unknown
        # streams validate against the base shape, matching the single
        # event route's 422-before-404 ordering.
        events = [_validate(raw, fields) for raw in values["events"]]
        try:
            payload = self.service.add_batch(name, values["batch_id"], events)
        except StreamNotFoundError:
            raise _RequestError(404, "stream_not_found", f"unknown stream: {name}") from None
        except BatchIngestNotEnabledError:
            raise _RequestError(
                409, "batch_ingest_not_enabled", f"stream has no batch ingest: {name}"
            ) from None
        except BatchIdConflictError:
            raise _RequestError(
                409, "batch_id_conflict", f"conflicting batch_id: {values['batch_id']}"
            ) from None
        except EventIdConflictError as exc:
            raise _RequestError(
                409, "event_id_conflict", f"conflicting event_id: {exc}"
            ) from None
        except LookupKeyNotFoundError as exc:
            raise _RequestError(
                409, "lookup_key_not_found", f"unknown lookup_key: {exc}"
            ) from None
        except LookupVersionNotFoundError as exc:
            raise _RequestError(
                409, "lookup_version_not_found",
                f"no dimension version for lookup_key: {exc}",
            ) from None
        except StreamBackpressuredError:
            raise _RequestError(
                429, "stream_backpressured", f"stream has no open window slots: {name}"
            ) from None
        self.send_json(200, payload)

    def _advance_watermark(self, name: str) -> None:
        values = _validate(self._read_json(), _WATERMARK_FIELDS)
        try:
            payload = self.service.advance_watermark(name, values["watermark_ms"])
        except StreamNotFoundError:
            raise _RequestError(404, "stream_not_found", f"unknown stream: {name}") from None
        except WatermarkRegressionError:
            raise _RequestError(409, "watermark_regression", "watermark must not move backwards") from None
        self.send_json(200, payload)

    def _get_changes(self, name: str) -> None:
        after_seq, limit = self._changes_params()
        try:
            payload = self.service.changes(name, after_seq, limit)
        except StreamNotFoundError:
            raise _RequestError(404, "stream_not_found", f"unknown stream: {name}") from None
        except ChangeFeedNotEnabledError:
            raise _RequestError(
                409, "change_feed_not_enabled", f"stream has no change feed: {name}"
            ) from None
        except ChangeCursorAheadError:
            raise _RequestError(
                409, "change_cursor_ahead", f"cursor is past the latest seq: {after_seq}"
            ) from None
        except ChangeCursorExpiredError:
            raise _RequestError(
                410, "change_cursor_expired", f"cursor is behind the retained records: {after_seq}"
            ) from None
        self.send_json(200, payload)

    def _changes_params(self) -> tuple[int, int]:
        """Validate the after_seq/limit query pair of the changes route."""
        pairs = parse_qsl(urlsplit(self.path).query, keep_blank_values=True)
        names = sorted(key for key, _ in pairs)
        if len(pairs) != 2 or names != ["after_seq", "limit"]:
            raise _invalid_request(
                "expected exactly the query parameters: after_seq, limit"
            )
        raw = dict(pairs)
        after_seq = self._query_int("after_seq", raw["after_seq"])
        if after_seq < 0:
            raise _invalid_request("after_seq must be a non-negative integer")
        limit = self._query_int("limit", raw["limit"])
        if not 1 <= limit <= 1000:
            raise _invalid_request("limit must be between 1 and 1000")
        return after_seq, limit

    @staticmethod
    def _query_int(field: str, raw: str) -> int:
        if not raw.isdigit():
            raise _invalid_request(f"invalid value for query parameter: {field}")
        return int(raw)

    def _restore_snapshot(self) -> None:
        document = self._read_json()
        try:
            restored = self.service.restore_snapshot(document)
        except RestoreConflictError:
            raise _RequestError(
                409,
                "restore_conflict",
                "snapshot restore is only allowed on an instance without streams or tables",
            ) from None
        except SnapshotError as exc:
            raise _RequestError(422, "invalid_snapshot", str(exc)) from None
        self.send_json(200, {"restored_streams": restored})

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="streammill.server", description="流式仓库与实时分析引擎")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    state_file = env_state_file()
    if state_file is not None:
        # Persistent mode: any startup contract violation exits non-zero
        # before the server starts listening.
        try:
            Handler.service = Service.from_state_file(state_file)
        except StateFileError as exc:
            raise SystemExit(f"invalid STREAMMILL_STATE_FILE: {exc}") from None
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"StreamMill listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

            if kind not in ("upsert", "final"):
                raise SnapshotError(
                    f"stream {self.name!r}: change record kind must be "
                    f"'upsert' or 'final'"
                )
            if not _is_int(start):
                raise SnapshotError(
                    f"stream {self.name!r}: change record window_start_ms must "
                    f"be an integer"
                )
            if start % self._step_ms != 0:
                raise SnapshotError(
                    f"stream {self.name!r}: window {start} is not aligned to "
                    f"the window grid step {self._step_ms}"
                )
            if not _is_int(end) or end != start + self.window_ms:
                raise SnapshotError(
                    f"stream {self.name!r}: window {start} end must be "
                    f"{start + self.window_ms}"
                )
            if not _is_int(count) or count <= 0:
                raise SnapshotError(
                    f"stream {self.name!r}: window {start} count must be a "
                    f"positive integer"
                )
            if not _is_finite_number(total):
                raise SnapshotError(
                    f"stream {self.name!r}: window {start} sum must be a "
                    f"finite number"
                )
            if start not in known_windows:
                raise SnapshotError(
                    f"stream {self.name!r}: change record references unknown "
                    f"window {start}"
                )
            if start in final_seen:
                raise SnapshotError(
                    f"stream {self.name!r}: window {start} has records after "
                    f"its final record"
                )
            if kind == "final":
                if start not in self._finalized_starts:
                    raise SnapshotError(
                        f"stream {self.name!r}: window {start} has a final "
                        f"record but is not finalized"
                    )
                final_seen.add(start)
            record = {
                "seq": seq,
                "kind": kind,
                "window_start_ms": start,
                "window_end_ms": end,
                "count": count,
                "sum": total,
            }
            parsed.append(record)
            last_by_window[start] = record
        if parsed and parsed[-1]["seq"] != latest_seq:
            raise SnapshotError(
                f"stream {self.name!r}: latest_seq {latest_seq} does not match "
                f"the newest retained record"
            )
        finalized_by_start = {
            row["window_start_ms"]: row for row in self._finalized
        }
        for start, record in last_by_window.items():
            if start in self._windows:
                expected_kind = "upsert"
                expected_count, expected_sum = self._windows[start]
            else:
                expected_kind = "final"
                row = finalized_by_start[start]
                expected_count, expected_sum = row["count"], row["sum"]
            if record["kind"] != expected_kind:
                raise SnapshotError(
                    f"stream {self.name!r}: last retained record of window "
                    f"{start} must be a {expected_kind!r}"
                )
            if record["count"] != expected_count or not math.isclose(
                record["sum"], expected_sum, rel_tol=1e-9, abs_tol=1e-9
            ):
                raise SnapshotError(
                    f"stream {self.name!r}: last retained record of window "
                    f"{start} does not match the aggregated state"
                )
        self._changes = parsed
        self._latest_seq = latest_seq

    def _load_batch_records(self, records: object) -> None:
        """Load retained batch records under strict validation.

        The records are kept in commit order with unique identifiers and
        at most ``batch_retention`` of them; every request and response
        must match the shapes the batch entry point produces on this
        stream (event fields follow the stream's dedup/join features,
        outcomes follow its dedup/automatic features).
        """
        assert self.batch_retention is not None
        if not isinstance(records, list):
            raise SnapshotError(f"stream {self.name!r}: batches must be an array")
        if len(records) > self.batch_retention:
            raise SnapshotError(
                f"stream {self.name!r}: batches exceed batch_retention "
                f"{self.batch_retention}"
            )
        seen: set[str] = set()
        parsed: list[dict] = []
        for raw in records:
            if not isinstance(raw, dict):
                raise SnapshotError(
                    f"stream {self.name!r}: batches entries must be objects"
                )
            fields = {"batch_id", "request", "response"}
            extra = sorted(set(raw) - fields)
            if extra:
                raise SnapshotError(
                    f"stream {self.name!r}: batch record has unexpected field: "
                    f"{extra[0]}"
                )
            missing = sorted(fields - set(raw))
            if missing:
                raise SnapshotError(
                    f"stream {self.name!r}: batch record missing field: "
                    f"{missing[0]}"
                )
            batch_id = raw["batch_id"]
            if not isinstance(batch_id, str) or not batch_id:
                raise SnapshotError(
                    f"stream {self.name!r}: batch_id must be a non-empty string"
                )
            if batch_id in seen:
                raise SnapshotError(
                    f"stream {self.name!r}: duplicate batch_id {batch_id!r}"
                )
            seen.add(batch_id)
            request = self._parse_batch_request(raw["request"], batch_id)
            response = self._parse_batch_response(
                raw["response"], batch_id, len(request["events"])
            )
            parsed.append(
                {"batch_id": batch_id, "request": request, "response": response}
            )
        self._batches = parsed

    def _parse_batch_request(self, raw: object, batch_id: str) -> dict:
        if not isinstance(raw, dict):
            raise SnapshotError(
                f"stream {self.name!r}: batch request must be an object"
            )
        fields = {"batch_id", "events"}
        extra = sorted(set(raw) - fields)
        if extra:
            raise SnapshotError(
                f"stream {self.name!r}: batch request has unexpected field: "
                f"{extra[0]}"
            )
        missing = sorted(fields - set(raw))
        if missing:
            raise SnapshotError(
                f"stream {self.name!r}: batch request missing field: {missing[0]}"
            )
        if raw["batch_id"] != batch_id:
            raise SnapshotError(
                f"stream {self.name!r}: batch request batch_id does not match "
                f"the record"
            )
        events = raw["events"]
        if not isinstance(events, list) or not 1 <= len(events) <= 1000:
            raise SnapshotError(
                f"stream {self.name!r}: batch events must be an array of "
                f"1 to 1000 elements"
            )
        return {
            "batch_id": batch_id,
            "events": [self._parse_batch_event(event) for event in events],
        }

    def _parse_batch_event(self, raw: object) -> dict:
        if not isinstance(raw, dict):
            raise SnapshotError(
                f"stream {self.name!r}: batch events entries must be objects"
            )
        fields = {"timestamp_ms", "value"}
        if self.dedup_retention_ms is not None:
            fields |= {"event_id"}
        if self.lookup_table is not None:
            fields |= {"lookup_key"}
        extra = sorted(set(raw) - fields)
        if extra:
            raise SnapshotError(
                f"stream {self.name!r}: batch event has unexpected field: "
                f"{extra[0]}"
            )
        missing = sorted(fields - set(raw))
        if missing:
            raise SnapshotError(
                f"stream {self.name!r}: batch event missing field: {missing[0]}"
            )
        if not _is_int(raw["timestamp_ms"]):
            raise SnapshotError(
                f"stream {self.name!r}: batch event timestamp_ms must be an integer"
            )
        if not _is_finite_number(raw["value"]):
            raise SnapshotError(
                f"stream {self.name!r}: batch event value must be a finite number"
            )
        event = {"timestamp_ms": raw["timestamp_ms"], "value": raw["value"]}
        if self.dedup_retention_ms is not None:
            if not isinstance(raw["event_id"], str) or not raw["event_id"]:
                raise SnapshotError(
                    f"stream {self.name!r}: batch event event_id must be a "
                    f"non-empty string"
                )
            event["event_id"] = raw["event_id"]
        if self.lookup_table is not None:
            if not isinstance(raw["lookup_key"], str) or not raw["lookup_key"]:
                raise SnapshotError(
                    f"stream {self.name!r}: batch event lookup_key must be a "
                    f"non-empty string"
                )
            event["lookup_key"] = raw["lookup_key"]
        return event

    def _parse_batch_response(
        self, raw: object, batch_id: str, event_count: int
    ) -> dict:
        if not isinstance(raw, dict):
            raise SnapshotError(
                f"stream {self.name!r}: batch response must be an object"
            )
        fields = {"stream", "batch_id", "outcomes"}
        extra = sorted(set(raw) - fields)
        if extra:
            raise SnapshotError(
                f"stream {self.name!r}: batch response has unexpected field: "
                f"{extra[0]}"
            )
        missing = sorted(fields - set(raw))
        if missing:
            raise SnapshotError(
                f"stream {self.name!r}: batch response missing field: {missing[0]}"
            )
        if raw["stream"] != self.name:
            raise SnapshotError(
                f"stream {self.name!r}: batch response labels stream "
                f"{raw['stream']!r}"
            )
        if raw["batch_id"] != batch_id:
            raise SnapshotError(
                f"stream {self.name!r}: batch response batch_id does not match "
                f"the record"
            )
        outcomes = raw["outcomes"]
        if not isinstance(outcomes, list) or len(outcomes) != event_count:
            raise SnapshotError(
                f"stream {self.name!r}: batch response outcomes must be an "
                f"array matching the events"
            )
        return {
            "stream": self.name,
            "batch_id": batch_id,
            "outcomes": [self._parse_batch_outcome(row) for row in outcomes],
        }

    def _parse_batch_outcome(self, raw: object) -> dict:
        if not isinstance(raw, dict):
            raise SnapshotError(
                f"stream {self.name!r}: batch outcome must be an object"
            )
        fields = {"dropped"}
        if self.dedup_retention_ms is not None:
            fields |= {"duplicate"}
        if self.auto_watermark_lag_ms is not None:
            fields |= {"watermark_ms", "finalized"}
        extra = sorted(set(raw) - fields)
        if extra:
            raise SnapshotError(
                f"stream {self.name!r}: batch outcome has unexpected field: "
                f"{extra[0]}"
            )
        missing = sorted(fields - set(raw))
        if missing:
            raise SnapshotError(
                f"stream {self.name!r}: batch outcome missing field: {missing[0]}"
            )
        if not isinstance(raw["dropped"], bool):
            raise SnapshotError(
                f"stream {self.name!r}: batch outcome dropped must be a boolean"
            )
        outcome = {"dropped": raw["dropped"]}
        if self.dedup_retention_ms is not None:
            if not isinstance(raw["duplicate"], bool):
                raise SnapshotError(
                    f"stream {self.name!r}: batch outcome duplicate must be a "
                    f"boolean"
                )
            outcome["duplicate"] = raw["duplicate"]
        if self.auto_watermark_lag_ms is not None:
            watermark = raw["watermark_ms"]
            if watermark is not None and not _is_int(watermark):
                raise SnapshotError(
                    f"stream {self.name!r}: batch outcome watermark_ms must be "
                    f"an integer or null"
                )
            rows = self._parse_window_list(
                raw["finalized"],
                self.name,
                self.window_ms,
                "batch outcome finalized",
                with_stream=True,
                step_ms=self._step_ms,
            )
            for row in rows:
                if row["stream"] != self.name:
                    raise SnapshotError(
                        f"stream {self.name!r}: batch outcome finalized row "
                        f"labels stream {row['stream']!r}"
                    )
            outcome["watermark_ms"] = watermark
            outcome["finalized"] = [dict(row) for row in rows]
        return outcome


class Service:
    """StreamMill service: health reporting plus windowed event aggregation."""

    name = "streammill"
    version = __version__

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._streams: dict[str, _Stream] = {}
        # table name -> _Table; in-process dimension tables.
        self._tables: dict[str, _Table] = {}
        # Path of the local persistent state file; None keeps the pure
        # in-memory behavior. Set only through from_state_file.
        self._state_file: str | None = None

    @classmethod
    def from_state_file(cls, path: str) -> "Service":
        """Build a service durably backed by the state file at ``path``.

        This is the startup contract of ``STREAMMILL_STATE_FILE``: the
        path must be a non-empty string, must not point at a directory,
        and its parent directory must exist and be writable. A missing
        file starts an empty instance; an existing file must be valid
        UTF-8 JSON forming a snapshot document the restore entry point
        accepts, and is loaded completely before the service is used.
        Every violation raises StateFileError and no state is published;
        loading never silently repairs invalid content. Once built,
        every successful state-changing request is persisted as one
        complete snapshot before its success is returned.
        """
        if not isinstance(path, str) or not path:
            raise StateFileError("state file path must be a non-empty string")
        if os.path.isdir(path):
            raise StateFileError(f"state file path is a directory: {path!r}")
        parent = os.path.dirname(os.path.abspath(path))
        if not os.path.isdir(parent):
            raise StateFileError(
                f"state file parent directory does not exist: {parent!r}"
            )
        if not os.access(parent, os.W_OK):
            raise StateFileError(
                f"state file parent directory is not writable: {parent!r}"
            )
        service = cls()
        if os.path.exists(path):
            try:
                with open(path, "rb") as handle:
                    raw = handle.read()
            except OSError as exc:
                raise StateFileError(
                    f"state file is not readable: {exc}"
                ) from exc
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError as exc:
                raise StateFileError(
                    f"state file is not valid UTF-8: {exc}"
                ) from exc
            try:
                document = json.loads(text)
            except ValueError as exc:
                raise StateFileError(
                    f"state file is not valid JSON: {exc}"
                ) from exc
            try:
                service.restore_snapshot(document)
            except SnapshotError as exc:
                raise StateFileError(
                    f"state file is not an accepted snapshot: {exc}"
                ) from exc
        # Persistence is enabled only after the load succeeded, so the
        # startup restore itself never writes the file back.
        service._state_file = path
        return service

    def _commit_locked(self, mutate):
        """Run one state-changing operation as a single durable commit.

        The caller must hold the service lock. With no state file
        configured the mutation simply runs. Otherwise the pre-commit
        snapshot is kept; a mutation that leaves the public state
        unchanged (a too-late drop, an exact duplicate, an identical row
        value or watermark, a retained batch replay) writes nothing. A
        changed state is persisted as one complete snapshot while the
        lock is still held — so commits persist in exactly the lock
        order — and only then does the commit return. If the write
        fails, the in-memory state is rolled back to the pre-commit
        snapshot, the file keeps the previous complete commit, and
        StatePersistError is raised: the request is as if it never
        happened. A mutation that itself raises never touches the file.
        """
        if self._state_file is None:
            return mutate()
        backup = self._snapshot_locked()
        result = mutate()
        document = self._snapshot_locked()
        if document != backup:
            try:
                _write_state_file(self._state_file, document)
            except OSError as exc:
                self._restore_document_locked(backup)
                raise StatePersistError(
                    f"failed to persist state file {self._state_file!r}: {exc}"
                ) from exc
        return result

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def create_table(self, name: str, event_time_versioned: bool = False) -> dict:
        with self._lock:

            def commit() -> None:
                if name in self._tables:
                    raise TableExistsError(name)
                self._tables[name] = _Table(event_time_versioned)

            self._commit_locked(commit)
        payload = {"table": name}
        if event_time_versioned:
            payload["event_time_versioned"] = True
        return payload

    def table_features(self, name: str) -> dict | None:
        """Row-surface features of the table; None if it is unknown."""
        with self._lock:
            table = self._tables.get(name)
            if table is None:
                return None
            return {"event_time_versioned": table.event_time_versioned}

    def put_row(self, table: str, key: str, label: str) -> dict:
        with self._lock:

            def commit() -> bool:
                target = self._tables.get(table)
                if target is None:
                    raise TableNotFoundError(table)
                changed = target.rows.get(key) != label
                target.rows[key] = label
                return changed

            changed = self._commit_locked(commit)
        return {"table": table, "key": key, "label": label, "changed": changed}

    def put_version_row(
        self, table: str, key: str, label: str, effective_from_ms: int
    ) -> dict:
        """Insert one version into an event-time versioned table.

        Out-of-order writes are accepted; an identical retry reports
        ``changed: False`` and a conflicting label at an existing point
        raises DimensionVersionConflictError with the history untouched.
        """
        with self._lock:

            def commit() -> bool:
                target = self._tables.get(table)
                if target is None:
                    raise TableNotFoundError(table)
                return target.put_version(key, label, effective_from_ms)

            changed = self._commit_locked(commit)
        return {
            "table": table,
            "key": key,
            "label": label,
            "effective_from_ms": effective_from_ms,
            "changed": changed,
        }

    def create_stream(
        self,
        name: str,
        window_ms: int,
        allowed_lateness_ms: int,
        dedup_retention_ms: int | None = None,
        auto_watermark_lag_ms: int | None = None,
        slide_ms: int | None = None,
        lookup_table: str | None = None,
        change_retention: int | None = None,
        batch_retention: int | None = None,
        max_open_windows: int | None = None,
    ) -> dict:
        with self._lock:

            def commit() -> None:
                if name in self._streams:
                    raise StreamExistsError(name)
                if lookup_table is not None and lookup_table not in self._tables:
                    raise TableNotFoundError(lookup_table)
                self._streams[name] = _Stream(
                    name,
                    window_ms,
                    allowed_lateness_ms,
                    dedup_retention_ms,
                    auto_watermark_lag_ms,
                    slide_ms,
                    lookup_table,
                    change_retention,
                    batch_retention,
                    max_open_windows,
                )

            self._commit_locked(commit)
        payload = {
            "stream": name,
            "window_ms": window_ms,
            "allowed_lateness_ms": allowed_lateness_ms,
        }
        if dedup_retention_ms is not None:
            payload["dedup_retention_ms"] = dedup_retention_ms
        if auto_watermark_lag_ms is not None:
            payload["auto_watermark_lag_ms"] = auto_watermark_lag_ms
        if slide_ms is not None:
            payload["slide_ms"] = slide_ms
        if lookup_table is not None:
            payload["lookup_table"] = lookup_table
        if change_retention is not None:
            payload["change_retention"] = change_retention
        if batch_retention is not None:
            payload["batch_retention"] = batch_retention
        if max_open_windows is not None:
            payload["max_open_windows"] = max_open_windows
        return payload

    def stream_features(self, name: str) -> dict | None:
        """Event-surface features of the stream; None if it is unknown."""
        with self._lock:
            stream = self._streams.get(name)
            if stream is None:
                return None
            return {
                "dedup": stream.dedup_retention_ms is not None,
                "join": stream.lookup_table is not None,
            }

    def add_event(
        self,
        name: str,
        timestamp_ms: int,
        value: float,
        event_id: str | None = None,
        lookup_key: str | None = None,
    ) -> dict:
        with self._lock:

            def commit() -> dict:
                stream = self._get(name)
                return stream.add_event(
                    timestamp_ms, value, event_id, lookup_key, self._label_of(stream)
                )

            outcome = self._commit_locked(commit)
        return {"stream": name, **outcome}

    def add_batch(self, name: str, batch_id: str, events: list[dict]) -> dict:
        """Apply one atomic batch of events to a batch-enabled stream.

        The whole call runs under the service lock, so no other request
        can observe an intermediate state. A retained record with the
        same ``batch_id`` and an identical request (same field values in
        the same event order) replays its stored response without
        writing again; the same id with different content raises
        BatchIdConflictError. A processing failure rolls the whole batch
        back and occupies no identifier. Only successful batches are
        remembered, capped at the stream's ``batch_retention`` newest
        records; replaying never refreshes that order.
        """
        with self._lock:
            stream = self._get(name)
            if stream.batch_retention is None:
                raise BatchIngestNotEnabledError(name)
            for record in stream._batches:
                if record["batch_id"] == batch_id:
                    if record["request"]["events"] == events:
                        # A retained replay returns the stored response
                        # without writing, so it is not a commit.
                        return copy.deepcopy(record["response"])
                    raise BatchIdConflictError(batch_id)

            def commit() -> dict:
                outcomes = stream.apply_batch(events, self._label_of(stream))
                response = {"stream": name, "batch_id": batch_id, "outcomes": outcomes}
                stream._batches.append(
                    {
                        "batch_id": batch_id,
                        "request": {
                            "batch_id": batch_id,
                            "events": copy.deepcopy(events),
                        },
                        "response": copy.deepcopy(response),
                    }
                )
                overflow = len(stream._batches) - stream.batch_retention
                if overflow > 0:
                    del stream._batches[:overflow]
                return response

            return self._commit_locked(commit)

    def _label_of(self, stream: _Stream):
        """Label reader for a joined stream, else None.

        The reader takes ``(lookup_key, timestamp_ms)``: a current-value
        table ignores the timestamp and an unknown key raises
        LookupKeyNotFoundError, while a versioned table resolves the
        newest version effective at the event's own timestamp and raises
        LookupVersionNotFoundError when none exists.
        """
        if stream.lookup_table is None:
            return None
        table = self._tables[stream.lookup_table]
        if table.event_time_versioned:

            def label_of(key: str, timestamp_ms: int, _table=table) -> str:
                return _table.label_at(key, timestamp_ms)

            return label_of
        rows = table.rows

        def label_of(key: str, timestamp_ms: int, _rows=rows) -> str:
            try:
                return _rows[key]
            except KeyError:
                raise LookupKeyNotFoundError(key) from None

        return label_of

    def advance_watermark(self, name: str, watermark_ms: int) -> dict:
        with self._lock:

            def commit() -> list[dict]:
                return self._get(name).advance_watermark(watermark_ms)

            finalized = self._commit_locked(commit)
        return {"stream": name, "watermark_ms": watermark_ms, "finalized": finalized}

    def results(self, name: str) -> dict:
        with self._lock:
            rows = self._get(name).results()
        return {"stream": name, "results": rows}

    def joined_results(self, name: str) -> dict:
        with self._lock:
            stream = self._get(name)
            if stream.lookup_table is None:
                raise JoinNotEnabledError(name)
            rows = [dict(row) for row in stream._joined_finalized]
        return {"stream": name, "results": rows}

    def pressure(self, name: str) -> dict:
        """Open-window pressure of a backpressured stream.

        Only base windows that are not yet finalized occupy slots —
        sliding windows count separately, joined groups, finalized
        results and change records never do. The read happens under the
        service lock, so it only ever observes complete commits.
        """
        with self._lock:
            stream = self._get(name)
            if stream.max_open_windows is None:
                raise BackpressureNotEnabledError(name)
            open_windows = stream._open_window_count()
            max_open_windows = stream.max_open_windows
        return {
            "stream": name,
            "max_open_windows": max_open_windows,
            "open_windows": open_windows,
            "available_windows": max_open_windows - open_windows,
        }

    def changes(self, name: str, after_seq: int, limit: int) -> dict:
        """Read retained change-feed records with ``seq`` greater than
        ``after_seq``, ascending, at most ``limit`` of them.

        The read happens under the service lock, so it only ever observes
        complete commits. A cursor past the latest sequence raises
        ChangeCursorAheadError; a cursor older than the oldest retained
        record (so records were trimmed past it) raises
        ChangeCursorExpiredError.
        """
        with self._lock:
            stream = self._get(name)
            if stream.change_retention is None:
                raise ChangeFeedNotEnabledError(name)
            if after_seq > stream._latest_seq:
                raise ChangeCursorAheadError(
                    f"cursor {after_seq} is ahead of latest_seq "
                    f"{stream._latest_seq}"
                )
            retained = stream._changes
            if retained and after_seq < retained[0]["seq"] - 1:
                raise ChangeCursorExpiredError(
                    f"cursor {after_seq} is behind the oldest retained "
                    f"record (seq {retained[0]['seq']})"
                )
            if retained:
                offset = max(0, after_seq - retained[0]["seq"] + 1)
                records = [dict(row) for row in retained[offset : offset + limit]]
            else:
                records = []
            latest_seq = stream._latest_seq
        return {"stream": name, "latest_seq": latest_seq, "changes": records}

    def snapshot(self) -> dict:
        """Return a consistent point-in-time, JSON-serializable snapshot.

        The whole document is assembled while holding the service lock, so
        concurrent creates, events and watermark advances are either fully
        included or fully excluded. Instances with at least one
        backpressured stream export ``format_version`` 6 (always carrying
        the ``tables`` array, and ``max_open_windows`` on the enabled
        streams); otherwise instances with at least one versioned
        dimension table export ``format_version`` 5 (always carrying
        the ``tables`` array with each table's mode, versioned rows ordered by
        key then effective time); otherwise instances with at least one
        batch-enabled stream export ``format_version`` 4, instances with
        at least one change-feed stream export ``format_version`` 3,
        instances with dimension tables export ``format_version`` 2, and
        without any join, change-feed, batch or versioned state the
        document is the unchanged version 1 shape.
        """
        with self._lock:
            return self._snapshot_locked()

    def _snapshot_locked(self) -> dict:
        """Assemble the snapshot document; the caller holds the lock."""
        streams = [
            self._streams[name].to_snapshot() for name in sorted(self._streams)
        ]
        tables = [self._table_to_snapshot(name) for name in sorted(self._tables)]
        if any(
            stream.max_open_windows is not None
            for stream in self._streams.values()
        ):
            return {
                "format_version": SNAPSHOT_FORMAT_VERSION_BACKPRESSURE,
                "tables": tables,
                "streams": streams,
            }
        if any(
            table.event_time_versioned for table in self._tables.values()
        ):
            return {
                "format_version": SNAPSHOT_FORMAT_VERSION_VERSIONED_TABLES,
                "tables": tables,
                "streams": streams,
            }
        batches = any(
            stream.batch_retention is not None
            for stream in self._streams.values()
        )
        if batches:
            return {
                "format_version": SNAPSHOT_FORMAT_VERSION_BATCHES,
                "tables": tables,
                "streams": streams,
            }
        change_feed = any(
            stream.change_retention is not None
            for stream in self._streams.values()
        )
        if change_feed:
            return {
                "format_version": SNAPSHOT_FORMAT_VERSION_CHANGES,
                "tables": tables,
                "streams": streams,
            }
        if self._tables:
            return {
                "format_version": SNAPSHOT_FORMAT_VERSION_JOIN,
                "tables": tables,
                "streams": streams,
            }
        return {
            "format_version": SNAPSHOT_FORMAT_VERSION,
            "streams": streams,
        }

    def _table_to_snapshot(self, name: str) -> dict:
        """Serialize one table as one entry of the snapshot's tables array."""
        table = self._tables[name]
        if table.event_time_versioned:
            versions = []
            for key in sorted(table.versions):
                for effective_from_ms, label in table.versions[key]:
                    versions.append(
                        {
                            "key": key,
                            "label": label,
                            "effective_from_ms": effective_from_ms,
                        }
                    )
            return {
                "name": name,
                "event_time_versioned": True,
                "versions": versions,
            }
        return {
            "name": name,
            "rows": [
                {"key": key, "label": table.rows[key]}
                for key in sorted(table.rows)
            ],
        }

    def restore_snapshot(self, document: object) -> int:
        """Replace instance state with a validated snapshot, atomically.

        Only callable on an instance without streams or tables; otherwise
        raises RestoreConflictError, regardless of document content. Any
        invalid document raises SnapshotError and leaves the (empty)
        instance untouched. Version 1 documents restore as before;
        version 2 documents additionally restore dimension tables and
        joined-stream state under strict validation; version 3 documents
        additionally restore change-feed state (retention, cursor and
        retained records) under strict validation; version 4 documents
        additionally restore batch-ingest state (retention and the
        retained batch records, so replay and eviction continue exactly
        as on the uninterrupted instance); version 5 documents
        additionally restore event-time versioned tables (mode markers
        and version timelines) under strict validation; version 6
        documents additionally restore open-window backpressure (the
        per-stream ``max_open_windows`` limit, with at least one enabled
        stream whose open base windows must not exceed it) under strict
        validation. Returns the restored stream count.
        """
        with self._lock:
            # Conflict takes priority over every content check: an instance
            # with streams or tables always gets restore_conflict.
            if self._streams or self._tables:
                raise RestoreConflictError(
                    "restore is only allowed on an instance without streams "
                    "or tables"
                )
            return self._commit_locked(
                lambda: self._restore_document_locked(document)
            )

    def _restore_document_locked(self, document: object) -> int:
        """Validate and publish one snapshot document; caller holds the lock.

        Every structural and semantic rule is checked before the single
        publishing assignment at the end, so an invalid document raises
        SnapshotError and leaves the instance untouched. Also used to
        roll the in-memory state back to a kept snapshot when a persist
        fails mid-commit; such documents are self-generated and always
        valid. Returns the restored stream count.
        """
        if not isinstance(document, dict):
            raise SnapshotError("snapshot document must be a JSON object")
        if "format_version" not in document:
            raise SnapshotError(
                "snapshot document missing required field: format_version"
            )
        version = document["format_version"]
        if not _is_int(version):
            raise SnapshotError("format_version must be an integer")
        tables_versions = (
            SNAPSHOT_FORMAT_VERSION_JOIN,
            SNAPSHOT_FORMAT_VERSION_CHANGES,
            SNAPSHOT_FORMAT_VERSION_BATCHES,
            SNAPSHOT_FORMAT_VERSION_VERSIONED_TABLES,
            SNAPSHOT_FORMAT_VERSION_BACKPRESSURE,
        )
        if version == SNAPSHOT_FORMAT_VERSION:
            allowed = {"format_version", "streams"}
        elif version in tables_versions:
            allowed = {"format_version", "streams", "tables"}
        else:
            raise SnapshotError(f"unsupported format_version: {version}")
        extra = sorted(set(document) - allowed)
        if extra:
            raise SnapshotError(
                f"snapshot document has unexpected field: {extra[0]}"
            )
        missing = sorted(allowed - set(document))
        if missing:
            raise SnapshotError(
                f"snapshot document missing required field: {missing[0]}"
            )
        entries = document["streams"]
        if not isinstance(entries, list):
            raise SnapshotError("streams must be an array")

        tables: dict[str, _Table] = {}
        if version in tables_versions:
            tables = self._parse_tables(
                document["tables"],
                allow_versioned=(
                    version
                    in (
                        SNAPSHOT_FORMAT_VERSION_VERSIONED_TABLES,
                        SNAPSHOT_FORMAT_VERSION_BACKPRESSURE,
                    )
                ),
            )

        # Build and validate everything before the single publishing
        # assignment, so a failure leaves no partial state and concurrent
        # requests never observe half-restored streams.
        restored: dict[str, _Stream] = {}
        previous_name: str | None = None
        for entry in entries:
            stream = _Stream.from_snapshot(
                entry,
                table_names=set(tables) if version in tables_versions else None,
                allow_change_feed=version
                in (
                    SNAPSHOT_FORMAT_VERSION_CHANGES,
                    SNAPSHOT_FORMAT_VERSION_BATCHES,
                    SNAPSHOT_FORMAT_VERSION_VERSIONED_TABLES,
                    SNAPSHOT_FORMAT_VERSION_BACKPRESSURE,
                ),
                allow_batches=version
                in (
                    SNAPSHOT_FORMAT_VERSION_BATCHES,
                    SNAPSHOT_FORMAT_VERSION_VERSIONED_TABLES,
                    SNAPSHOT_FORMAT_VERSION_BACKPRESSURE,
                ),
                allow_backpressure=(
                    version == SNAPSHOT_FORMAT_VERSION_BACKPRESSURE
                ),
            )
            if stream.name in restored:
                raise SnapshotError(
                    f"duplicate stream name in snapshot: {stream.name!r}"
                )
            if previous_name is not None and stream.name <= previous_name:
                raise SnapshotError("streams must be strictly ordered by name")
            previous_name = stream.name
            restored[stream.name] = stream
        if version == SNAPSHOT_FORMAT_VERSION_BACKPRESSURE and not any(
            stream.max_open_windows is not None for stream in restored.values()
        ):
            raise SnapshotError(
                "format_version 6 requires at least one stream with "
                "max_open_windows"
            )
        self._tables = tables
        self._streams = restored
        return len(restored)

    @staticmethod
    def _parse_tables(value: object, allow_versioned: bool = False) -> dict:
        """Validate the ``tables`` array of a snapshot document.

        Current-value tables carry ``name``/``rows``; versioned tables
        (only accepted in a version 5 document) carry ``name``,
        ``event_time_versioned: true`` and ``versions`` strictly ordered
        by key then effective time. Nothing is repaired: any malformed
        mode combination, duplicate or out-of-order point raises
        SnapshotError.
        """
        if not isinstance(value, list):
            raise SnapshotError("tables must be an array")
        tables: dict[str, _Table] = {}
        previous_name: str | None = None
        for entry in value:
            if not isinstance(entry, dict):
                raise SnapshotError("table entries must be objects")
            declared = {"name", "rows"}
            if allow_versioned:
                declared |= {"event_time_versioned", "versions"}
            extra = sorted(set(entry) - declared)
            if extra:
                raise SnapshotError(f"table entry has unexpected field: {extra[0]}")
            if "name" not in entry:
                raise SnapshotError("table entry missing required field: name")
            name = entry["name"]
            if not isinstance(name, str) or not name:
                raise SnapshotError("table name must be a non-empty string")
            if previous_name is not None and name <= previous_name:
                raise SnapshotError("tables must be strictly ordered by name")
            previous_name = name
            if "event_time_versioned" in entry:
                if entry["event_time_versioned"] is not True:
                    raise SnapshotError(
                        f"table {name!r}: event_time_versioned must be true "
                        f"when present"
                    )
                if "rows" in entry:
                    raise SnapshotError(
                        f"table {name!r}: rows present on a versioned table"
                    )
                if "versions" not in entry:
                    raise SnapshotError(
                        f"table entry missing required field: versions"
                    )
                tables[name] = Service._parse_versioned_table(
                    name, entry["versions"]
                )
            else:
                if "versions" in entry:
                    raise SnapshotError(
                        f"table {name!r}: versions present without "
                        f"event_time_versioned"
                    )
                if "rows" not in entry:
                    raise SnapshotError(
                        f"table entry missing required field: rows"
                    )
                tables[name] = Service._parse_current_table(name, entry["rows"])
        return tables

    @staticmethod
    def _parse_current_table(name: str, raw_rows: object) -> _Table:
        """Validate the rows of a current-value table entry."""
        if not isinstance(raw_rows, list):
            raise SnapshotError(f"table {name!r}: rows must be an array")
        table = _Table()
        previous_key: str | None = None
        for raw in raw_rows:
            if not isinstance(raw, dict):
                raise SnapshotError(f"table {name!r}: rows entries must be objects")
            extra = sorted(set(raw) - {"key", "label"})
            if extra:
                raise SnapshotError(
                    f"table {name!r}: row has unexpected field: {extra[0]}"
                )
            missing = sorted({"key", "label"} - set(raw))
            if missing:
                raise SnapshotError(
                    f"table {name!r}: row missing required field: {missing[0]}"
                )
            key = raw["key"]
            label = raw["label"]
            if not isinstance(key, str) or not key:
                raise SnapshotError(
                    f"table {name!r}: row key must be a non-empty string"
                )
            if not isinstance(label, str) or not label:
                raise SnapshotError(
                    f"table {name!r}: row label must be a non-empty string"
                )
            if previous_key is not None and key <= previous_key:
                raise SnapshotError(
                    f"table {name!r}: rows must be strictly ordered by key"
                )
            previous_key = key
            table.rows[key] = label
        return table

    @staticmethod
    def _parse_versioned_table(name: str, raw_versions: object) -> _Table:
        """Validate the version timeline of a versioned table entry.

        Every point carries ``key``/``label``/``effective_from_ms`` and
        the array is strictly ordered by ``(key, effective_from_ms)``,
        which rejects duplicate points, out-of-order versions and
        conflicting points at the same effective time alike.
        """
        if not isinstance(raw_versions, list):
            raise SnapshotError(f"table {name!r}: versions must be an array")
        table = _Table(event_time_versioned=True)
        previous: tuple | None = None
        for raw in raw_versions:
            if not isinstance(raw, dict):
                raise SnapshotError(
                    f"table {name!r}: versions entries must be objects"
                )
            fields = {"key", "label", "effective_from_ms"}
            extra = sorted(set(raw) - fields)
            if extra:
                raise SnapshotError(
                    f"table {name!r}: version has unexpected field: {extra[0]}"
                )
            missing = sorted(fields - set(raw))
            if missing:
                raise SnapshotError(
                    f"table {name!r}: version missing required field: {missing[0]}"
                )
            key = raw["key"]
            label = raw["label"]
            effective_from_ms = raw["effective_from_ms"]
            if not isinstance(key, str) or not key:
                raise SnapshotError(
                    f"table {name!r}: version key must be a non-empty string"
                )
            if not isinstance(label, str) or not label:
                raise SnapshotError(
                    f"table {name!r}: version label must be a non-empty string"
                )
            if not _is_int(effective_from_ms):
                raise SnapshotError(
                    f"table {name!r}: version effective_from_ms must be an integer"
                )
            point = (key, effective_from_ms)
            if previous is not None and point <= previous:
                raise SnapshotError(
                    f"table {name!r}: versions must be strictly ordered by "
                    f"key and effective_from_ms"
                )
            previous = point
            table.versions.setdefault(key, []).append((effective_from_ms, label))
        return table

    def _get(self, name: str) -> _Stream:
        try:
            return self._streams[name]
        except KeyError:
            raise StreamNotFoundError(name) from None

import json
